package com.dataengine.governance.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="governance_notification") public class GovernanceNotification {
 @Id private UUID id; @Column(nullable=false) private String recipient; @Column(nullable=false) private String category; @Column(nullable=false) private String title; @Column(nullable=false,length=1000) private String content; private UUID changeId; @Enumerated(EnumType.STRING) @Column(nullable=false) private NotificationStatus status; @Column(nullable=false) private Instant createdAt; private Instant readAt;
 protected GovernanceNotification(){} public GovernanceNotification(String recipient,String category,String title,String content,UUID changeId){id=UUID.randomUUID();this.recipient=recipient;this.category=category;this.title=title;this.content=content;this.changeId=changeId;status=NotificationStatus.UNREAD;createdAt=Instant.now();} public void markRead(){status=NotificationStatus.READ;readAt=Instant.now();} public UUID getId(){return id;} public String getRecipient(){return recipient;} public String getCategory(){return category;} public String getTitle(){return title;} public String getContent(){return content;} public UUID getChangeId(){return changeId;} public NotificationStatus getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} public Instant getReadAt(){return readAt;}
}
